-- Generated by ekos-lakehouse (RFC 0195) from marts/film_catalog_by_rating.md. Approve by merging; do not edit.
{{ config(materialized='table', schema='gold', alias='film_catalog_by_rating') }}

select
    "film"."rating" as "rating",
    count("film"."film_id") as "films",
    avg("film"."rental_rate") as "average_rental_rate",
    avg("film"."length") as "average_length",
    sum("film"."replacement_cost") as "total_replacement_cost"
from {{ ref('public__film') }} as "film"
group by "film"."rating"
